package com.rulecraft.decisionops.runtime;

import com.rulecraft.decisionops.audit.AuditService;
import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;
import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.domain.ExpressionValidationStatus;import com.rulecraft.decisionops.expressions.language.ExpressionLanguage;
import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;
import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectAccessPolicy;import com.rulecraft.decisionops.runtime.types.TypedValueValidator;
import com.rulecraft.decisionops.tables.DecisionTableService;import com.rulecraft.decisionops.tables.domain.*;
import java.util.*;import java.util.stream.Collectors;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.core.JacksonException;import tools.jackson.databind.*;

@Service
public class DecisionExecutionService {
    private final ProjectAccessPolicy access;private final CatalogService catalog;private final DecisionGraphService graphs;private final DecisionTableService tableService;private final DecisionExpressionService expressionService;private final ExpressionLanguage language;private final TypedValueValidator typedValues;private final AuditService audit;private final ObjectMapper mapper;
    public DecisionExecutionService(ProjectAccessPolicy access,CatalogService catalog,DecisionGraphService graphs,DecisionTableService tableService,DecisionExpressionService expressionService,ExpressionLanguage language,TypedValueValidator typedValues,AuditService audit,ObjectMapper mapper){this.access=access;this.catalog=catalog;this.graphs=graphs;this.tableService=tableService;this.expressionService=expressionService;this.language=language;this.typedValues=typedValues;this.audit=audit;this.mapper=mapper;}
    @Transactional public EvaluationView evaluate(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,EvaluationCommand command){access.requireVisible(actor,projectId);var service=catalog.getService(actor,projectId,serviceId);var graph=graphs.get(actor,projectId,serviceId);if(graph.validationStatus()!=GraphValidationStatus.VALID||!graph.issues().isEmpty())bad("RC-EXEC-GRAPH-INVALID","Resolve graph validation issues before evaluating this decision service.");var supplied=command==null||command.inputs()==null?Map.<String,JsonNode>of():command.inputs();validateInputs(service,supplied);var incoming=graph.edges().stream().collect(Collectors.toMap(GraphEdgeView::targetPortId,GraphEdgeView::sourcePortId));var values=new HashMap<UUID,JsonNode>();var resolved=new HashSet<UUID>();
        for(var node:graph.nodes().stream().filter(value->value.kind()==GraphNodeKind.INPUT).toList()){var value=supplied.get(node.serviceFieldKey());for(var port:node.ports().stream().filter(item->item.direction()==GraphPortDirection.OUTPUT).toList()){resolved.add(port.id());if(value!=null)values.put(port.id(),value);}}
        var remaining=new ArrayList<>(graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.DECISION).sorted(Comparator.comparing(GraphNodeView::nodeKey)).toList());var decisions=new ArrayList<DecisionEvaluation>();
        while(!remaining.isEmpty()){var ready=remaining.stream().filter(node->node.ports().stream().filter(port->port.direction()==GraphPortDirection.INPUT).map(GraphPortView::id).map(incoming::get).filter(Objects::nonNull).allMatch(resolved::contains)).findFirst().orElseThrow(()->problem("RC-EXEC-ORDER","The decision graph could not be ordered deterministically."));var context=new LinkedHashMap<String,JsonNode>();for(var port:ready.ports().stream().filter(item->item.direction()==GraphPortDirection.INPUT).sorted(Comparator.comparingInt(GraphPortView::position)).toList()){var source=incoming.get(port.id());if(source!=null&&values.containsKey(source))context.put(port.portKey(),values.get(source));}var result=evaluateDecision(actor,projectId,serviceId,ready,context);var output=ready.ports().stream().filter(port->port.direction()==GraphPortDirection.OUTPUT).findFirst().orElseThrow();values.put(output.id(),result.value());resolved.add(output.id());decisions.add(result);remaining.remove(ready);}
        var outputs=new LinkedHashMap<String,JsonNode>();for(var field:service.outputs()){var node=graph.nodes().stream().filter(value->value.kind()==GraphNodeKind.OUTPUT&&Objects.equals(value.serviceFieldKey(),field.fieldKey())).findFirst().orElseThrow();var target=node.ports().stream().filter(port->port.direction()==GraphPortDirection.INPUT).findFirst().orElseThrow();var source=incoming.get(target.id());var value=source==null?null:values.get(source);if(value==null){if(field.required())bad("RC-EXEC-OUTPUT-MISSING","The required output '"+field.fieldKey()+"' was not produced.");}else outputs.put(field.fieldKey(),value);}
        var evaluationId=UUID.randomUUID();audit.record(actor.tenantId(),actor.userId(),"DECISION_SANDBOX_EVALUATED","DECISION_SERVICE",serviceId,Map.of("evaluationId",evaluationId,"graphVersion",graph.version(),"decisions",decisions.size(),"outputs",outputs.keySet()));return new EvaluationView(evaluationId,serviceId,graph.version(),outputs,decisions);
    }
    private DecisionEvaluation evaluateDecision(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,GraphNodeView node,Map<String,JsonNode> context){var table=tableService.find(actor,projectId,serviceId,node.id());var expression=expressionService.find(actor,projectId,serviceId,node.id());if(table.isPresent()&&expression.isPresent())bad("RC-EXEC-IMPLEMENTATION-AMBIGUOUS","A decision cannot have both a table and expression implementation.");if(table.isEmpty()&&expression.isEmpty())bad("RC-EXEC-IMPLEMENTATION-MISSING","Decision '"+node.nodeKey()+"' does not have an implementation.");if(table.isPresent()){var value=table.get();if(value.validationStatus()!=TableValidationStatus.VALID||!value.issues().isEmpty())bad("RC-EXEC-TABLE-INVALID","Decision table '"+node.nodeKey()+"' is not valid.");var matches=value.rules().stream().filter(rule->rule.enabled()&&rule.inputs().stream().allMatch(entry->entry.operator()==InputOperator.ANY||Objects.equals(context.get(value.inputs().stream().filter(column->column.portId().equals(entry.inputPortId())).findFirst().orElseThrow().portKey()),parse(entry.valueJson())))).toList();if(matches.isEmpty())bad("RC-EXEC-NO-MATCH","Decision table '"+node.nodeKey()+"' did not match any rule.");if(value.hitPolicy()==HitPolicy.UNIQUE&&matches.size()!=1)bad("RC-EXEC-UNIQUE-VIOLATION","A UNIQUE decision table matched more than one rule.");var matched=matches.getFirst();return new DecisionEvaluation(node.id(),node.nodeKey(),node.name(),"TABLE",value.version(),matched.id(),parse(matched.outputValueJson()));}var value=expression.orElseThrow();if(value.validationStatus()!=ExpressionValidationStatus.VALID||!value.issues().isEmpty())bad("RC-EXEC-EXPRESSION-INVALID","Decision expression '"+node.nodeKey()+"' is not valid.");var inputs=node.ports().stream().filter(port->port.direction()==GraphPortDirection.INPUT).sorted(Comparator.comparingInt(GraphPortView::position)).toList();var output=node.ports().stream().filter(port->port.direction()==GraphPortDirection.OUTPUT).findFirst().orElseThrow();var evaluated=language.evaluate(value.source(),inputs,output,context);if(!evaluated.successful()){var issue=evaluated.issues().getFirst();bad(issue.code(),issue.message());}return new DecisionEvaluation(node.id(),node.nodeKey(),node.name(),"EXPRESSION",value.version(),null,evaluated.value());}
    private void validateInputs(DecisionServiceView service,Map<String,JsonNode> supplied){validateInputBudget(supplied);var expected=service.inputs().stream().map(FieldView::fieldKey).collect(Collectors.toSet());var unknown=supplied.keySet().stream().filter(key->!expected.contains(key)).findFirst();if(unknown.isPresent())bad("RC-EXEC-INPUT-UNKNOWN","Unknown service input '"+unknown.get()+"'.");for(var field:service.inputs()){var value=supplied.get(field.fieldKey());if(value==null){if(field.required())bad("RC-EXEC-INPUT-MISSING","Provide required input '"+field.fieldKey()+"'.");}else if(!typedValues.valid(value,field.type().builtinType(),field.type().customTypeId()))bad("RC-EXEC-INPUT-TYPE","Input '"+field.fieldKey()+"' does not match its declared type.");}}
    private void validateInputBudget(Map<String,JsonNode> supplied){var pending=new ArrayDeque<JsonNode>();supplied.values().stream().filter(Objects::nonNull).forEach(pending::add);var nodes=0;while(!pending.isEmpty()){var value=pending.removeFirst();if(++nodes>10_000||(value.isArray()&&value.size()>2_000)||(value.isString()&&value.asString().length()>12_000))bad("RC-EXEC-INPUT-LIMIT","Evaluation inputs exceed the sandbox size limits.");value.values().forEach(pending::addLast);}}
    private JsonNode parse(String raw){try{return mapper.readTree(raw);}catch(JacksonException failure){throw problem("RC-EXEC-PERSISTED-VALUE","A persisted rule value is not valid JSON.");}}private void bad(String code,String message){throw problem(code,message);}private DomainProblemException problem(String code,String message){return new DomainProblemException(HttpStatus.BAD_REQUEST,code,message);}
    public record EvaluationCommand(Map<String,JsonNode> inputs){}
    public record DecisionEvaluation(UUID nodeId,String nodeKey,String nodeName,String implementation,long implementationVersion,UUID matchedRuleId,JsonNode value){}
    public record EvaluationView(UUID evaluationId,UUID decisionServiceId,long graphVersion,Map<String,JsonNode> outputs,List<DecisionEvaluation> decisions){}
}
